checkpoint_metrics AS (
  SELECT
    -- ─── A. EXACT CHUNK 06 ID & CUMULATIVE POPULATION RECONCILIATION ────────────
    (SELECT count(*) FROM expected_chunk_06_ids) AS chunk_06_expected_ids_count,

    (SELECT count(*) FROM expected_chunk_06_ids e
     JOIN public.constituency_demographics d ON d.id = e.id) AS chunk_06_ids_present_count,

    (SELECT count(*) FROM expected_chunk_06_ids e
     LEFT JOIN public.constituency_demographics d ON d.id = e.id
     WHERE d.id IS NULL) AS chunk_06_ids_missing_count,

    (SELECT count(*) FROM public.constituency_demographics) AS total_demographics_in_table,

    (SELECT count(*) FROM public.constituency_demographics d
     LEFT JOIN authorized_cumulative_ids c ON c.id = d.id
     WHERE c.id IS NULL) AS unexpected_demographics_count,

    (SELECT count(*) FROM (
       SELECT id FROM public.constituency_demographics GROUP BY id HAVING count(*) > 1
     ) dup) AS duplicate_ids_count,

    (SELECT count(*) FROM public.constituency_demographics 
     WHERE id IS NULL OR id::text NOT LIKE '0215b22e-0003-0000-0000-%') AS non_namespace_demographics_count,

    (SELECT min(id::text) FROM public.constituency_demographics) AS min_demographic_id_observed,
    (SELECT max(id::text) FROM public.constituency_demographics) AS max_demographic_id_observed,

    -- ─── B. STATE SCOPE & CUMULATIVE PARTITION BOUNDARIES (8 STATES) ────────────
    (SELECT count(*) FROM public.constituency_demographics 
     WHERE state_code IS NULL OR state_code NOT IN (
       'AP', 'AR', 'AS', 'BR', 'CG', 'DL', 'GA', 'GJ'
     )) AS foreign_state_demographics_count,

    (SELECT count(DISTINCT state_code) FROM public.constituency_demographics) AS distinct_states_observed,

    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'AP') AS ap_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'AR') AS ar_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'AS') AS as_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'BR') AS br_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'CG') AS cg_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'DL') AS dl_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'GA') AS ga_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'GJ') AS gj_count,

    -- ─── C. DELHI ASSEMBLY INTEGRITY (70 ACS & ZERO WARD POLLUTION) ─────────────
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'DL' AND constituency_code LIKE 'DL-AC-%') AS dl_canonical_ac_count,
    (SELECT count(*) FROM public.constituency_demographics WHERE state_code = 'DL' AND constituency_code NOT LIKE 'DL-AC-%') AS dl_ward_pollution_count,

    -- ─── D. REFERENTIAL INTEGRITY & ZERO ORPHANS ─────────────────────────────────
    (SELECT count(*) FROM public.constituency_demographics d
     LEFT JOIN public.constituencies c ON c.internal_id = d.constituency_id
     WHERE d.constituency_id IS NULL OR c.internal_id IS NULL) AS orphan_constituencies_count,

    (SELECT count(*) FROM public.constituency_demographics d
     LEFT JOIN public.provenance_records pr ON pr.id = d.provenance_id
     WHERE d.provenance_id IS NULL OR pr.id IS NULL) AS orphan_provenance_count,

    (SELECT count(*) FROM public.constituency_demographics 
     WHERE provenance_id IS NULL OR provenance_id <> '0215b22e-0000-0000-0000-000000000001'::uuid) AS non_b2_2e_provenance_count,

    -- ─── E. DATA QUALITY & CLASSIFICATION (100% ESTIMATE) ───────────────────────
    (SELECT count(*) FROM public.constituency_demographics 
     WHERE data_status IS NULL OR data_status::text <> 'ESTIMATE') AS invalid_status_count,

    (SELECT count(*) FROM public.constituency_demographics 
     WHERE constituency_code IS NULL OR constituency_code !~ '^[A-Z]{2}-AC-[0-9]{3}$') AS invalid_code_format_count,

    (SELECT count(*) FROM public.constituency_demographics 
     WHERE ac_no IS NULL OR ac_no <= 0) AS invalid_ac_no_count,

    (SELECT count(*) FROM public.constituency_demographics 
     WHERE election_year IS NULL OR election_year NOT IN (2020, 2021, 2022, 2023, 2024)) AS invalid_election_year_count,

    -- ─── F. PROTECTED TABLE BASELINES (STRICT PRESERVATION) ──────────────────────
    (SELECT count(*) FROM public.candidate_affidavits) AS candidate_affidavits_count,
    (SELECT count(*) FROM public.candidacies) AS candidacies_count,
    (SELECT count(*) FROM public.canonical_persons) AS canonical_persons_count,
    (SELECT count(*) FROM public.political_organizations) AS political_organizations_count,
    (SELECT count(*) FROM public.constituencies) AS constituencies_count,
    (SELECT count(*) FROM public.states) AS states_count,
    (SELECT count(*) FROM public.constituency_lineage) AS constituency_lineage_count,
    (SELECT count(*) FROM public.provenance_records) AS provenance_records_count
)
SELECT
  jsonb_build_object(
    'checkpoint', 'W021.5-B2.2-E_CHUNK_06_ACCEPTANCE_CHECKPOINT',
    'timestamp', now(),
    'chunk_identity', jsonb_build_object(
      'chunk_id', '06',
      'scope', 'Canonical Constituency Demographics Part 1 (AP, AR, AS, BR, CG, DL, GA, GJ)',
      'expected_chunk_ids', chunk_06_expected_ids_count,
      'chunk_ids_present', chunk_06_ids_present_count,
      'chunk_ids_missing', chunk_06_ids_missing_count,
      'unexpected_ids', unexpected_demographics_count,
      'table_total_observed', total_demographics_in_table,
      'duplicate_ids', duplicate_ids_count,
      'non_namespace_ids', non_namespace_demographics_count,
      'min_id_observed', min_demographic_id_observed,
      'max_id_observed', max_demographic_id_observed,
      'status', CASE 
        WHEN chunk_06_expected_ids_count = 986 
         AND chunk_06_ids_present_count = 986 
         AND chunk_06_ids_missing_count = 0 
         AND unexpected_demographics_count = 0
         AND total_demographics_in_table = 986
         AND duplicate_ids_count = 0
         AND non_namespace_demographics_count = 0
         AND min_demographic_id_observed = '0215b22e-0003-0000-0000-000000000001'
         AND max_demographic_id_observed = '0215b22e-0003-0000-0000-000000000986'
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'state_scope', jsonb_build_object(
      'foreign_state_records', foreign_state_demographics_count,
      'distinct_states', distinct_states_observed,
      'chunk_06_states', jsonb_build_object(
        'AP', ap_count, 'AR', ar_count, 'AS', as_count, 'BR', br_count,
        'CG', cg_count, 'DL', dl_count, 'GA', ga_count, 'GJ', gj_count
      ),
      'status', CASE 
        WHEN foreign_state_demographics_count = 0 
         AND distinct_states_observed = 8 
         AND ap_count = 175 AND ar_count = 60 AND as_count = 126 AND br_count = 243
         AND cg_count = 90 AND dl_count = 70 AND ga_count = 40 AND gj_count = 182
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'delhi_assembly_integrity', jsonb_build_object(
      'dl_canonical_ac_count', dl_canonical_ac_count,
      'dl_ward_pollution_count', dl_ward_pollution_count,
      'status', CASE 
        WHEN dl_canonical_ac_count = 70 AND dl_ward_pollution_count = 0 
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'referential_integrity', jsonb_build_object(
      'orphan_constituencies', orphan_constituencies_count,
      'orphan_provenance', orphan_provenance_count,
      'non_b2_2e_provenance', non_b2_2e_provenance_count,
      'status', CASE 
        WHEN orphan_constituencies_count = 0 
         AND orphan_provenance_count = 0 
         AND non_b2_2e_provenance_count = 0
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'data_integrity', jsonb_build_object(
      'invalid_status_count', invalid_status_count,
      'invalid_code_format_count', invalid_code_format_count,
      'invalid_ac_no_count', invalid_ac_no_count,
      'invalid_election_year_count', invalid_election_year_count,
      'status', CASE 
        WHEN invalid_status_count = 0 
         AND invalid_code_format_count = 0 
         AND invalid_ac_no_count = 0 
         AND invalid_election_year_count = 0 
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'protected_baselines', jsonb_build_object(
      'candidate_affidavits', candidate_affidavits_count,
      'candidacies', candidacies_count,
      'canonical_persons', canonical_persons_count,
      'political_organizations', political_organizations_count,
      'constituencies', constituencies_count,
      'states', states_count,
      'constituency_lineage', constituency_lineage_count,
      'provenance_records', provenance_records_count,
      'status', CASE 
        WHEN candidate_affidavits_count = 4523
         AND candidacies_count = 11298 
         AND canonical_persons_count = 9083 
         AND political_organizations_count = 107 
         AND constituencies_count = 4123 
         AND states_count = 36 
         AND constituency_lineage_count = 126 
         AND provenance_records_count = 2456 
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'verdict', (
      CASE 
        WHEN chunk_06_expected_ids_count = 986
         AND chunk_06_ids_present_count = 986
         AND chunk_06_ids_missing_count = 0
         AND unexpected_demographics_count = 0
         AND total_demographics_in_table = 986
         AND duplicate_ids_count = 0
         AND non_namespace_demographics_count = 0
         AND min_demographic_id_observed = '0215b22e-0003-0000-0000-000000000001'
         AND max_demographic_id_observed = '0215b22e-0003-0000-0000-000000000986'
         AND foreign_state_demographics_count = 0
         AND distinct_states_observed = 8
         AND ap_count = 175 AND ar_count = 60 AND as_count = 126 AND br_count = 243
         AND cg_count = 90 AND dl_count = 70 AND ga_count = 40 AND gj_count = 182
